  "sim.egg-incubator.title": "たまごインキュベーター",
  "sim.egg-incubator.desc": "孵化場で温度・湿度・卵の回転を管理し、孵化率を最大化します。",
  "sim.dairy-farm.title": "酪農場",
  "sim.dairy-farm.desc": "小規模な酪農を運営：給餌スケジュール、搾乳サイクル、群れの健康管理で収益を最大化します。",
  "sim.poultry-farm.title": "養鶏場",
  "sim.poultry-farm.desc": "商業養鶏場を管理 — ブロイラーとレイヤーの群れのための給餌、健康、生産目標に取り組みます。",
  "sim.cattle-dairy.title": "畜産＆酪農",
  "sim.cattle-dairy.desc": "牧場と酪農ユニットを統括し、放牧地の管理、繁殖、乳生産のバランスを取ります。",
  "sim.sheep-farm.title": "羊の牧場",
  "sim.sheep-farm.desc": "季節サイクルで羊を運営：子羊の出産、毛刈り、市場販売を行います。",
  "sim.network-noc.title": "ネットワークNOC",
  "sim.network-noc.desc": "ネットワーク運用センジンのエンジニアとして行動し、プレッシャー下で稼働中のインフラ障害を診断・解決します。",
  "sim.mobile-repair.title": "モバイル修理ワークショップ",
  "sim.mobile-repair.desc": "スマートフォンを診断・修理 — 画面交換、バッテリーの不具合、マザーボードの故障を対応します。",
  "sim.laptop-repair.title": "ラップトップ修理ワークショップ",
  "sim.laptop-repair.desc": "ノートPCをトラブルシュートして修理：ハードウェアの不具合、BIOSの問題、部品交換に対応します。",
  "sim.perfume-lab.title": "パフュームラボ",
  "sim.perfume-lab.desc": "精油と香り成分をブレンドして、シグネチャーフレグランスを作り、品質基準をクリアします。",
  "sim.detergent-lab.title": "洗剤ラボ",
  "sim.detergent-lab.desc": "洗浄製品を調合 — 界面活性剤、フィラー、性能テストのバランスを予算内で整えます。",
  "sim.skin-care-lab.title": "スキンケアラボ",
  "sim.skin-care-lab.desc": "化粧品の処方を開発・検証し、安全基準と有効性の目標を満たします。",
  "sim.woodworking.title": "木工ワークショップ",
  "sim.woodworking.desc": "オーダーメイドの木工店を運営：案件を計画し、材料を管理し、家具を期限内かつ予算内で納品します。",
  "sim.aluminum-glazing.title": "アルミ＆ガラス",
  "sim.aluminum-glazing.desc": "見積もりから現場完了まで、アルミ加工とガラス取り付けの事業を管理します。",
  "sim.global-kitchen.title": "グローバルキッチン",
  "sim.global-kitchen.desc": "レストランの厨房を率いる：メニュー、スタッフ、コスト、サービスシフトごとの顧客満足度を管理します。",
  "sim.chocolate-factory.title": "チョコレート工場",
  "sim.chocolate-factory.desc": "菓子工場を運営 — カカオの調達、生産スケジュール、品質管理を行います。",
  "sim.solar-energy.title": "太陽エネルギープラント",
  "sim.solar-energy.desc": "太陽光設備を設計・運用 — パネルのサイズ決定、系統への売電管理、ROIの追跡を行います。",
  "sim.hvac-systems.title": "HVACシステム",
  "sim.hvac-systems.desc": "商業ビル向けに、暖房・換気・空調システムを設置し、保守します。",
  "sim.logistics-supply.title": "物流＆サプライチェーン",
  "sim.logistics-supply.desc": "倉庫業務、車両ルート、取引先との関係を最適化して、納品KPIを達成します。",
  "sim.barber-salon.title": "理容室",
  "sim.barber-salon.desc": "理容室を運営：予約、スタッフのシフト、料金、顧客維持の戦略を管理します。",
  "sim.board-surgeon.title": "ボードサージョン",
  "sim.board-surgeon.desc": "模擬手術室で重大な手術判断を行う — 時間管理と患者の安全。",
  "sim.english-journey.title": "英語ジャーニー",
  "sim.english-journey.desc": "学習者を構造化された英語プログラムに沿って案内し、さまざまなスキルレベルに合わせて調整します。",
  "sim.music-training.title": "音楽トレーニングスタジオ",
  "sim.music-training.desc": "音楽教室を運営：レッスンをスケジュールし、楽器を管理し、発表会に向けた生徒の進捗を追跡します。",
  "sim.trade-tycoon.title": "トレードタイクーン",
  "sim.trade-tycoon.desc": "取引の帝国を築く — 安く買って高く売る。複数の市場で在庫とキャッシュフローを管理します。",
  "sim.vehicle-diagnostics.title": "車両診断＆修理シミュレーター",
  "sim.vehicle-diagnostics.desc": "OBD-IIの故障コードを診断し、電気系の不具合を追跡し、実際の自動車修理ワークフローを管理します。",
  "sim.marine-vessel.title": "海上船舶の追跡＆海事ロジスティクス",
  "sim.marine-vessel.desc": "グローバルな船隊を指揮 — 船舶を追跡し、港の混雑、天候の緊急事態、運河の遅延に対応します。",
