  "jungle.scene6": "負傷した鳥を見つけた。どうする？",
  "jungle.s6c1": "注意深く運ぶ — 道が開けるかも（+5 HP, +25 pts）",
  "jungle.s6c2": "見捨てる — 世話にエネルギーを使う（0 HP, +10 pts）",
  "jungle.scene7": "川が行く手を塞いでいる。水は速そうだ。",
  "jungle.s7c1": "倒木でいかだを作る（−5 HP, +40 pts）",
  "jungle.s7c2": "上流へ歩いて浅瀬を探す（+10 HP, +20 pts）",
  "jungle.scene8": "遠くに煙が見える。",
  "jungle.s8c1": "煙の方へ向かう — 救助かもしれない（+15 HP, +45 pts）",
  "jungle.s8c2": "避ける — 山火事かもしれない（−5 HP, +15 pts）",
  "jungle.scene9": "夜が来た。身を守る場所が必要だ。",
  "jungle.s9c1": "高い木に登って捕食者から身を守る（+10 HP, +30 pts）",
  "jungle.s9c2": "枝で地上のシェルターを作る（−5 HP, +35 pts）",
  "jungle.scene10": "見覚えのない果物を見つけた。とても空腹だ。",
  "jungle.s10c1": "食べる — 飢えている！（−20 HP, +30 pts）",
  "jungle.s10c2": "まずは少し肌で試す（0 HP, +20 pts）",
  "jungle.scene11": "大きなヘビが道を取り巻くようにうねっている。",
  "jungle.s11c1": "ゆっくり後退して迂回路を探す（+5 HP, +30 pts）",
  "jungle.s11c2": "追い払おうとする（−25 HP, +40 pts）",
  "jungle.scene12": "滝の音が聞こえる — 水が限界的に少ない。",
  "jungle.s12c1": "音を頼りに新しい水を探す（+20 HP, +35 pts）",
  "jungle.s12c2": "無視して進むだけ（−15 HP, +20 pts）",
  "jungle.scene13": "嵐が急速に近づいている。",
  "jungle.s13c1": "高台を見つけて身を隠す（+10 HP, +25 pts）",
  "jungle.s13c2": "逃げるために動き続ける（−10 HP, +30 pts）",
  "jungle.scene14": "洞窟を見つけた。暗くなってきた。",
  "jungle.s14c1": "洞窟に入って身を守る（+15 HP, +30 pts）",
  "jungle.s14c2": "木の下で眠る — 洞窟が占有されているかも（+5 HP, +20 pts）",
  "jungle.scene15": "疲れ切った。先にある空き地は安全そうだ。",
  "jungle.s15c1": "休んで回復する（+20 HP, +20 pts）",
  "jungle.s15c2": "押し進める — ここでは休むのが危険（−5 HP, +30 pts）",
  "jungle.scene16": "木に刻まれた古い地図を見つけた。",
  "jungle.s16c1": "地図の指す方向へ進む（+5 HP, +40 pts）",
  "jungle.s16c2": "無視する — 情報が古いかもしれない（0 HP, +10 pts）",
  "jungle.scene17": "凶暴なイノシシが行く手を横切る。",
  "jungle.s17c1": "最寄りの木にすぐ登る（+5 HP, +30 pts）",
  "jungle.s17c2": "その場に踏みとどまり、叫ぶ（−20 HP, +35 pts）",
  "jungle.scene18": "物資のある放棄されたキャンプを見つけた。",
  "jungle.s18c1": "役に立つものは全部取る（+20 HP, +50 pts）",
  "jungle.s18c2": "置いといて—あとで誰かが必要になるかもしれない（HP 0、+10 pts）",
  "jungle.scene19": "サルがあなたの食べ物バッグを盗みました！",
  "jungle.s19c1": "サルを追いかける（−10 HP、+40 pts）",
  "jungle.s19c2": "放っておこう—そのエネルギーは無駄だ（HP +0、+15 pts）",
  "jungle.scene20": "頭上でヘリコプターの音がします。",
  "jungle.s20c1": "すぐに合図の焚き火を！（+30 HP、+60 pts）",
  "jungle.s20c2": "手を振って—見つけてくれるかも（+5 HP、+40 pts）",
