  "briscola.howTo.3": "トリックを取ってポイントを獲得—A=11、3=10、K=4、Q=3、J=2",
  "briscola.howTo.4": "すべてのカードを出し切った後の最高得点が勝ち",
  "card99.howTo.1": "カードを出して、累計が99以下に保つようにする",
  "card99.howTo.2": "特殊カード：K=0、Q=キープ、J=−10、A=1 または 11",
  "card99.howTo.3": "合計が99を超えるとライフを1つ失う",
  "card99.howTo.4": "最後まで残った人（ライフあり）の勝ち！",
  "dominoes.howTo.1": "ドミノチェーンの端の数字を合わせる",
  "dominoes.howTo.2": "オープンエンドに合う手札のタイルを出す",
  "dominoes.howTo.3": "出せない場合は山札から引く",
  "dominoes.howTo.4": "手札を最初に空にした人（または目に見える合計が最も少ない人）の勝ち！",
  "farkle.howTo.1": "6つのサイコロを振り、得点になるサイコロは別に取っておく",
  "farkle.howTo.2": "1s = 100 pts · 5s = 50 pts · 同種3つ = 目×100",
  "farkle.howTo.3": "振ってみてNO（得点）なら、それはファークル（FARKLE）—手番を失う！",
  "farkle.howTo.4": "ポイントを温存して確実にするか、リスク/リターンのためにもう一度振る",
  "quiz.howTo.1": "選択式の質問をできるだけ早く20問答える",
  "quiz.howTo.2": "各質問は3秒—素早く答えよう！",
  "quiz.howTo.3": "より速く正解するとボーナスポイントが増える",
  "quiz.howTo.4": "すべての質問を完了して最終ランクを見る",
  "memory.howTo.1": "2枚ずつめくって、同じペアを見つけよう",
  "memory.howTo.2": "一致していれば、そのまま表向きのままです",
  "memory.howTo.3": "一致しなければ、両方とも裏返して戻る—どこにあったか覚えておこう！",
  "memory.howTo.4": "できるだけ少ない手数でペアをすべて揃えて高得点を狙え",
  "word.howTo.1": "ごちゃまぜの文字を並べ替えて、隠された単語を作る",
  "word.howTo.2": "正しい順に文字をタップして答えを組み立てる",
  "word.howTo.3": "行き詰まったらヒントボタンを使ってください（ポイント消費）",
  "word.howTo.4": "8つの単語を完成させてパズルを終わらせよう",
  "hangman.howTo.1": "隠された単語を1文字ずつ当てよう",
  "hangman.howTo.2": "正しい文字＝単語内に表示される",
