  "kids.explorer.eco.bottle.explain": "プラスチックボトルをリサイクルすると資源を節約でき、埋立地や海に流れ出るのを防げます。",
  "kids.explorer.eco.bottle.explainWrong": "プラスチックボトルは新しいものにリサイクルできます。次はリサイクル用のゴミ箱を使ってみよう！",
