  "kids.explorer.eco.tap.leave": "そのまま流し続ける",
  "kids.explorer.eco.tap.explain": "蛇口を止めると、毎日たくさんのきれいな水を節約できます。",
  "kids.explorer.eco.tap.explainWrong": "流しっぱなしの蛇口は、たくさんの水を無駄にします。使っていないときは止めましょう。",
