  "kids.explorer.eco.ride.explainWrong": "車は燃料を使って汚染を生みます。短い移動なら歩くか自転車の方がきれいです。",
  "kids.explorer.eco.tree.prompt": "学校が庭を作る計画です。何を入れるべきですか？",
