  "kids.explorer.eco.tree.explainWrong": "木は私たちの空気をきれいにしてくれます。切り倒すのではなく、もっと植えるべきです。",
  "kids.explorer.eco.bag.prompt": "買い物に行きます。どんな袋を持っていきますか？",
