  "kids.explorer.eco.animal.ignore": "巣や卵に触る",
  "kids.explorer.eco.animal.explain": "野生の動物は、家を乱さずに見守るのがいちばんです。",
  "kids.explorer.eco.animal.explainWrong": "野生の巣に触ると、親鳥が逃げてしまうことがあります。観察するのが最適です。",
